/**
 * The creature types of CR 205.3m (Subtypes) and how they are written as a group (stage P29, D-134). The table is
 * the engine's `CREATURE_TYPES`, generated by `pnpm creature-types:generate` from the Comprehensive Rules text in
 * `docs/rules/` (a test compares the two), so nothing here lists a type by hand: the grammar tells a creature type
 * from any other capitalized word ("Other Elves you control") by asking the table, and finds the singular of a plural
 * by asking which type's plural it is.
 *
 * The plural of a type comes from English, never from a card: `regularPlurals` gives the forms its ending asks for
 * (a regular "s", "es" after s, x, z, ch and sh, "ies" after a consonant and y, "ves" after f and fe, where the
 * f and fe types that keep "s" are accepted too, since the table does not say which are which), and
 * `IRREGULAR_PLURALS` and `INVARIANT_TYPES` below are the only two places that name a type: the plurals no ending rule
 * gives ("Mice", "Children") and the types that are their own plural ("Merfolk", "Sheep"). `creature-types.test` loops
 * over every type of the table and proves each one reads in the singular and in each plural form, that no two types
 * share a form, and that the two lists name only types that are in the table and forms the ending rules do not
 * already give.
 */
import { CREATURE_TYPES as TABLE } from '@commander-arena/engine';

/** Every creature type of CR 205.3m, as the rules spell it (C’tan and Shi’ar with a typographic apostrophe). */
export const CREATURE_TYPES: ReadonlySet<string> = new Set(TABLE);

/**
 * The plural forms the ending of `type` asks for. The last word takes the ending ("Time Lord" is "Time Lords",
 * "Assembly-Worker" is "Assembly-Workers"). A type whose ending asks for two forms ("Elf": "Elves" and "Elfs") gives
 * both: the table cannot say which of "Wolves" and "Giraffes" is the right one for which, and a form no card prints
 * is read harmlessly.
 */
export function regularPlurals(type: string): string[] {
  if (/(?:s|x|z|ch|sh)$/.test(type)) return [`${type}es`];
  if (/[^aeiou]y$/.test(type)) return [`${type.slice(0, -1)}ies`];
  if (/fe?$/.test(type)) return [type.replace(/fe?$/, 'ves'), `${type}s`];
  return [`${type}s`];
}

/**
 * The plural forms no ending rule gives. These come from English usage, not from the text of a card: the 1000 shapes
 * of `reports/` show none of them (they hold "Zombies", "Dragons", "Skeletons", "Orcs", "Birds", "Frogs", "Otters",
 * "Rats", "Humans", "Squirrels", "Bats", "Juggernauts" and "Walls", all regular), so a form here is unverified against
 * a real Oracle text until one appears. The ending rule's own form is also read for each ("Mouses"), which is
 * harmless.
 */
export const IRREGULAR_PLURALS: Readonly<Record<string, readonly string[]>> = {
  Child: ['Children'],
  Cyberman: ['Cybermen'],
  Cyclops: ['Cyclopes'],
  Fungus: ['Fungi'],
  Hero: ['Heroes'],
  Homunculus: ['Homunculi'],
  Mouse: ['Mice'],
  Nautilus: ['Nautili'],
  Octopus: ['Octopi'],
  Ox: ['Oxen'],
  Pegasus: ['Pegasi'],
};

/** The types whose plural is the type itself ("Merfolk you control", "Sheep you control"). */
export const INVARIANT_TYPES: ReadonlySet<string> = new Set([
  'Aurochs',
  'Astartes',
  'Custodes',
  'Eldrazi',
  'Fish',
  'Kithkin',
  'Merfolk',
  'Moonfolk',
  // Stage P31 (D-140): verified against real Oracle text, Myr Battlesphere's "tap X untapped Myr you control" (golden corpus).
  'Myr',
  'Nephilim',
  'Sheep',
  'Thalakos',
  'Treefolk',
]);

/** The key a word is looked up by: the plain apostrophe and the typographic one are the same letter. */
const keyOf = (word: string): string => word.replaceAll('’', "'");

interface Reading {
  readonly type: string;
  /** True for a plural form, false for the singular, null for a word that is both. */
  readonly plural: boolean | null;
}

/**
 * Every word the table can be written with, singular and plural, and what it reads as. A plural form that two types
 * share is left out (nothing is guessed); a word that is the singular of a type is that type, whatever it is the
 * plural of.
 */
const INDEX: ReadonlyMap<string, Reading> = (() => {
  const forms = new Map<string, Set<string>>();
  for (const type of TABLE) {
    for (const form of [...regularPlurals(type), ...(IRREGULAR_PLURALS[type] ?? [])]) {
      const key = keyOf(form);
      forms.set(key, (forms.get(key) ?? new Set<string>()).add(type));
    }
  }
  const index = new Map<string, Reading>();
  for (const [key, types] of forms) {
    const [only] = types;
    if (types.size === 1 && only !== undefined) index.set(key, { type: only, plural: true });
  }
  for (const type of TABLE) {
    index.set(keyOf(type), { type, plural: INVARIANT_TYPES.has(type) ? null : false });
  }
  return index;
})();

/** What a word is as a creature type: the type, and whether the word is its plural, singular or both. */
export function readCreatureType(word: string): Reading | undefined {
  return INDEX.get(keyOf(word));
}

/**
 * The creature type a word names, in the singular or the plural, or undefined. A word that is a type as it stands
 * counts, and so does a plural form (`regularPlurals`, `IRREGULAR_PLURALS`); a word that is not one of them is not read
 * ("Elvs", "Tokens", "Creatures").
 */
export function creatureTypeOf(word: string): string | undefined {
  return readCreatureType(word)?.type;
}

/** The words of the table that are more than one word ("Time Lord"), with their plurals, longest first. */
export const MULTIWORD_FORMS: readonly string[] = [...INDEX.keys()]
  .filter((word) => word.includes(' '))
  .sort((a, b) => b.length - a.length);

/**
 * The first word, lowercased, that any form of the table starts with ("zombies", "time", "merfolk", "c’tan"), written
 * with both apostrophes: what a rule that may start with a group of creatures lists as its `leading` words, so the
 * dispatch of a rule follows the table and names no type.
 */
export const TYPE_LEADING_WORDS: readonly string[] = [
  ...new Set(
    [...INDEX.keys()].flatMap((key) => {
      const first = (key.split(' ')[0] ?? '').toLowerCase();
      return [first, first.replaceAll("'", '’')];
    }),
  ),
];
